     * @return void
     */
    public static function clearInstancePool($and_clear_all_references = false)
    {
      if ($and_clear_all_references) {
        foreach (IsadPeer::$instances as $instance) {
          $instance->clearAllReferences(true);
        }
      }
        IsadPeer::$instances = array();
    }
    
