     */
    public static function doSelectJoinUnidadDocumental(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(IsadPeer::DATABASE_NAME);
        }

        IsadPeer::addSelectColumns($criteria);
        $startcol = IsadPeer::NUM_HYDRATE_COLUMNS;
        UnidadDocumentalPeer::addSelectColumns($criteria);

        $criteria->addJoin(IsadPeer::UNIDADDOCUMENTAL_ID, UnidadDocumentalPeer::UNIDADDOCUMENTAL_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseIsadPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = IsadPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = IsadPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
