                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    UnidadDocumentalPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (Isad) to $obj2 (UnidadDocumental)
                $obj2->addIsad($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


