    /**
     * Selects a collection of Isad objects pre-filled with all related objects except UnidadDocumental.
     *
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of Isad objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptUnidadDocumental(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(IsadPeer::DATABASE_NAME);
        }

        IsadPeer::addSelectColumns($criteria);
        $startcol2 = IsadPeer::NUM_HYDRATE_COLUMNS;

        NivelDescripcionPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + NivelDescripcionPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(IsadPeer::NIVELDESCRIPCION_ID, NivelDescripcionPeer::NIVELDESCRIPCION_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseIsadPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = IsadPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = IsadPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = IsadPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                IsadPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined NivelDescripcion rows

                $key2 = NivelDescripcionPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = NivelDescripcionPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = NivelDescripcionPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    NivelDescripcionPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (Isad) to the collection in $obj2 (NivelDescripcion)
                $obj2->addIsad($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


